WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), hire_date) / 365 AS years_since_hire_date FROM employees WHERE hire_date > DATE '2023-03-23' AND manager_id IS NOT NULL) SELECT *, LAG(years_since_hire_date) OVER (PARTITION BY job_title, dept_id ORDER BY years_since_hire_date, id) AS prev_years_since_hire_date, LEAD(years_since_hire_date) OVER (PARTITION BY job_title, dept_id ORDER BY years_since_hire_date, id) AS next_years_since_hire_date, LAG(salary) OVER (PARTITION BY job_title, dept_id ORDER BY years_since_hire_date, id) AS prev_salary, ROW_NUMBER() OVER (PARTITION BY job_title, dept_id ORDER BY years_since_hire_date, id) AS event_seq FROM base
